INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(156,5,'best-taste-of-asia-2026-02-08','2026-02-08',NULL,7,NULL,NULL,NULL,NULL,8.5,'Solid Chinese spot in Kingsford. Quick service, decent portions and not too expensive',1,NULL,'published',1777789079,1777789079);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(157,227,'clam-bar-2024-07-06','2024-07-06','lunch',8,NULL,NULL,NULL,NULL,7.5,'Iconic spot that’s great for an upscale lunch/dinner in the CBD. Well known for their cheese burger which I think lived up to the hype. Wasn’t a huge fan of the other dishes but vibe is quite diner like and interesting.',1,NULL,'published',1777789615,1777789615);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(158,237,'don-t-tell-uncle-2025-11-25','2025-11-25','dinner',7.5,NULL,NULL,NULL,NULL,8.5,'Solid Indian food I thought, bonus points for eat club discount. If not for discount I’d lower overall rating to 7. Enjoyed the curries, naan and dips',1,NULL,'published',1777790048,1777790048);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(159,214,'matteo-downtown-2026-05-03','2026-05-03','dinner',8,NULL,NULL,NULL,NULL,8,'Really solid Italian spot, tasty pizzas and',1,NULL,'published',1777799078,1777799078);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(160,205,'armorica-grand-brasserie-2025-01-25','2025-01-25','lunch',7.5,NULL,NULL,NULL,NULL,9.5,'Pigged out for the AYCE steak frites. Managed to get down 1.5kg so was pretty worth. Bit unfortunate they charge so much per sauce ($5 each) , good deal overall though',1,NULL,'published',1777811442,1777811442);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(161,272,'cafe-monstera-2025-01-18','2025-01-18','brunch',7.5,NULL,NULL,NULL,NULL,7,'Great location next to the Mosman bay wharf. Cozy spot with not too much space inside. Classic range of brunch spots',1,NULL,'published',1777812594,1777812594);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(162,273,'grana-2025-02-16','2025-02-16','dinner',8,NULL,NULL,NULL,NULL,8,'Really solid Italian food, casual and upscale experience that doesn’t fully break the bank. Solid bread, pasta and meat dishes available',1,NULL,'published',1777813062,1777813062);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(163,274,'the-white-horse-2025-04-16','2025-04-16','dinner',8.5,NULL,NULL,NULL,NULL,7,'Really enjoyed the dim lit and quiet vibe in white horse. It’s a very unassuming place but its good food and romantic atmosphere. Best for date night or nice dinner with friends and family.',1,NULL,'published',1777813479,1777813479);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(164,275,'lana-2024-10-09','2024-10-09','dinner',8,NULL,NULL,NULL,NULL,7,replace(replace('Tasty food and nice presentation, definitely on the upper side of upscale but wouldn’t call it fine dining. Chefs\r\nMenu is a good bet for $160. It’s on the pricier side and I can see people not thinking it’s worth it.','\r',char(13)),'\n',char(10)),1,NULL,'published',1777847288,1777847288);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(165,276,'bouillon-l-entrecote-2024-08-26','2024-08-26','dinner',7.5,NULL,NULL,NULL,NULL,7,'Does all your classic French dishes like steak frites and crepe. It was quite good but nothing was super memorable. I’d recommend a visit once but if it’s not on the top of my visit to return.',0,NULL,'published',1777847990,1777848398);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(166,286,'poly-2024-04-05','2024-04-05','dinner',7.5,NULL,NULL,NULL,NULL,6,'Had the set menu when I went for $95.  Food and atmosphere was nice but the portions I found were quite small. Good for a nice outing but don’t expect to be full.',0,NULL,'published',1777878738,1777878752);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(167,287,'oborozuki-2024-03-28','2024-03-28','dinner',9,NULL,NULL,NULL,NULL,7,'Went here for a special occasion with friends and it was the perfect spot. The wooden tables, dim lighting and ceiling tall windows made it feel like a finer experience. Yes it’s expensive but you’re paying for the elevated food, service and location.',1,NULL,'published',1777879191,1777879949);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(168,232,'king-clarence-2024-02-15','2024-02-15','dinner',7.5,NULL,NULL,NULL,NULL,7,'Went here for a group dinner for 10 people. We ordered from the à la carte menu which had a blend of Asian dishes such as pork ssam, duck and claypot rice. I would say solid restaurant but probably wouldn’t go back. Good option for larger group.',1,NULL,'published',1777880311,1777880311);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(169,288,'alfie-s-2023-12-14','2023-12-14','dinner',9,NULL,NULL,NULL,NULL,8,'I’m a big fan of Alfies, mainly because it’s affordable steaks with good sides. Very casual and upscale vibe at the same time so you can treat it however you wish. It’s a very flexible venue for both food and drinks. Very convenient location and doesn’t break the bank',1,NULL,'published',1777881417,1777881417);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(170,289,'mapo-newtown-2023-12-10','2023-12-10','dessert',8,NULL,NULL,NULL,NULL,7,'Mapo is one of the best ice cream you can get in Newtown. It has a thicker and silkier texture compared to your usual Messina and always has flavours that are addictive.',1,NULL,'published',1777881713,1777881713);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(171,146,'fred-s-2023-08-06','2023-08-06','dinner',7.5,NULL,NULL,NULL,NULL,7.5,'Overall though it was okay. Highlight was definitely the open kitchen where you could see the chefs close up if you walked to the back of the restaurant. It’s an elevated experience but the price was just so disproportionate to the food. Ended up paying ~ 160pp but some of the dishes were tiny. Probably wouldn’t go back but its one of the bougier spots in Paddington.',0,NULL,'published',1777882691,1777882691);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(172,290,'midden-by-mark-olive-2023-07-18','2023-07-18','dinner',7,NULL,NULL,NULL,NULL,8,'This place was an interesting experience, having traditional Australian cuisine like damper, kangaroo and wallaby. It’s at the opera house so it’s definitely giving tourist vibes but went here with a big work group to try it nonetheless. Overall it was okay I feel like we weren’t amazed but it was a fun experience.',0,NULL,'published',1777883109,1777883109);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(173,291,'chaco-ramen-2023-06-21','2023-06-21','dinner',8,NULL,NULL,NULL,NULL,7,'Warm and cozy ramen spot. It’s really intimate and small so you may need to wait for a spot. It’s got such a good broth  and flavours. Good for a casual date night.',1,NULL,'published',1777883528,1777883545);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(174,111,'cucina-porto-2022-08-21','2022-08-21','dinner',7,NULL,NULL,NULL,NULL,6,'Food was okay but nothing special. It’s in the Star so it’s a bit of a fancier vibe. Probably wouldn’t go back.',0,NULL,'published',1777899245,1777899680);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(175,292,'the-rice-den-2023-03-29','2023-03-29','lunch',6.5,NULL,NULL,NULL,NULL,6.5,'Good spot but nothing special. Food does the job but don’t expect anything amazing. More of local spot in the area but wouldn’t travel specially for it.',0,NULL,'published',1777899669,1777899669);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(176,293,'eggshellent-cafe-randwick-2023-04-04','2023-04-04','brunch',8,NULL,NULL,NULL,NULL,7.5,'I give this cafe a solid 8, food presented well and tastes pretty good. Does the classics nicely including croissant eggs benedict and tornado scrambled eggs. IMO I think it’s one of the better cafes in the Randwick area',1,NULL,'published',1777900508,1777900570);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(177,294,'garfish-crows-nest-2023-04-27','2023-04-27','lunch',7,NULL,NULL,NULL,NULL,7.5,'Good selection of fish but took a while for the food to come out. I tried the swordfish which was a new experience for me. I liked there were quite a few fish to choose from. Probably wouldn’t go back but it’s one of the nicer restaurants in the area for a nice sit down meal.',1,NULL,'published',1777900749,1777900763);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(178,295,'scala-lane-2025-03-28','2025-03-28','dinner',8,NULL,NULL,NULL,NULL,7,'This one is a personal favourite. It’s tucked away in the alleyway behind Wynyard station making it a bit of a ‘hole in the wall’ type restaurant. The main thing for me is the intimate vibe, great for date night. Mostly lots points for the food being good but nothing special.',1,NULL,'published',1777901397,1777901418);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(179,296,'bar-lucia-2024-12-12','2024-12-12','dinner',8,NULL,NULL,NULL,NULL,6,'Went for $49 paella night set menu. Pretty small portions as expected but paella was not bad. Good place for a small group dinner in Potts point.',1,NULL,'published',1777928948,1777928948);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(180,139,'izgara-2023-05-23','2023-05-23','dinner',7.5,NULL,NULL,NULL,NULL,8,'Went here with a large group and had a big feed. Shared heaps of dishes and I was full by the end of it. The food didn’t have a wow factor from memory. There are other Turkish spots in Sydney that are doing a bit better',0,NULL,'published',1777929233,1777929233);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(181,298,'chester-white-cured-diner-2024-07-03','2024-07-03',NULL,9.5,NULL,NULL,NULL,NULL,7,'Really rate this place for a date night. The place is small and the staff are extremely friendly and welcoming. Sitting at the bar feels like a personal and up close experience. Their main thing is their meats and cheese which they do really well. I don’t usually like too much charcuterie and cheese pastas but the vibe did it for me. I’d recommend giving it a try.',1,NULL,'published',1777929918,1777929918);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(182,305,'brandons-paddington-2026-01-26','2026-01-26','lunch',9,NULL,NULL,NULL,NULL,7.5,'I really rate Brandon’s I thought the sandwiches were tasty and presented well. Loved this place for a casual coffee/matcha and bite to eat in Paddington.',1,NULL,'published',1777970440,1777970440);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(183,306,'10-william-st-2025-11-08','2025-11-08','lunch',9,NULL,NULL,NULL,NULL,6,'Popped into 10 William for an impromptu lunch date. We got lucky with a walk in table, I’d usually book if going here it’s pretty popular. Rated the pretzel which came with a super soft butter and honey.  The ragu and potatoes were also solid.',1,NULL,'published',1777971297,1777971297);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(184,308,'theeca-2025-06-28','2025-06-28','brunch',7,NULL,NULL,NULL,NULL,6,'Theeca for brunch is not my favourite just purely cause I think it’s overrated. The pancake is good but overpriced. Nice location in Darlinghurst, worth a visit if you’re going for the vibe but don’t expect value.',0,NULL,'published',1778019430,1778019466);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(185,308,'theeca-2025-12-13','2025-12-13','dinner',8,NULL,NULL,NULL,NULL,8,'Pretty good experience at Theeca wine bar. Lots of big groups and date nights happening. Indoor and outdoor seating gives good optionality for the vibe you want. I enjoyed the food, and the portions were good value in my opinion',1,NULL,'published',1778019674,1778019687);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(186,309,'red-lenny-2026-05-06','2026-05-06','lunch',6.5,NULL,NULL,NULL,NULL,8,'Sandwiches were okay but I think there’s way better in Sydney. The chips were also super salty. The best sandwich was the chicken schnitzel one.',1,NULL,'published',1778046753,1778046753);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(187,310,'kiroran-silk-road-uyghur-restaurant-2026-04-01','2026-04-01','dinner',8.5,NULL,NULL,NULL,NULL,10,'Can’t pass this one up for a big eats feed. The portions are massive and it’s just a solid place for big groups, sharing style for Uyghur food. Convenient spot in Chinatown.',1,NULL,'published',1778106826,1778106826);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(188,311,'boulevard-bakery-2026-03-22','2026-03-22','snack',8,NULL,NULL,NULL,NULL,8,'Little cafe spot in maroubra, really liked the pastries, coffee also solid too. Not much space inside to sit so it’s a 50/50 whether you can get a table.',1,NULL,'published',1778107026,1778107026);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(189,171,'happyfield-2023-07-08','2023-07-08','brunch',8,NULL,NULL,NULL,NULL,8,'Happyfield is an iconic breakfast/brunch spot in the inner west. Was a fan of the happy platter for 2 but still need to try the pancakes.',1,NULL,'published',1778107306,1778107306);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(190,314,'the-sanderson-sydney-2025-06-27','2025-06-27','dinner',8.5,NULL,NULL,NULL,NULL,9,'Massive steak, tasted pretty good I would say. Good char and on the raw side for medium rare which I don’t mind at all. The vibe feels very ‘game of thrones’ / ‘pirate’ with all the wooden/marble tables, staff and decor. Rate it for a birthday dinner or date. They gave me this cool little keychain knife as a gift for my birthday and they also let you pick a knife to eat hour steak with.',1,NULL,'published',1778218739,1778219396);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(191,131,'jambo-jambo-2026-05-08','2026-05-08','dinner',8.5,NULL,NULL,NULL,NULL,9,'Really interesting food experience, I highly recommend giving it a go. A mix of sour and herby flavours share style. You get a big platter to eat with a group and you can choose what meats and toppings you want. Rated the beef and lamb in particular. Chef and owner comes and says hi as well. It’s a merivale spot which automatically qualifies it for a price premium but I didn’t think it was as bad as some of their other spots',1,NULL,'published',1778291167,1778291436);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(192,316,'saray-turkish-pizza-and-kebabs-newtown-2026-05-07','2026-05-07','dinner',8.5,NULL,NULL,NULL,NULL,9,'Mad kebabs, they just tasted so good. I got the mixed kebab with bbq and sweet chilli. Was fantastic.',1,NULL,'published',1778500953,1778500953);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(193,277,'new-york-burgers-mac-pty-ltd-2026-05-15','2026-05-15','dinner',9,NULL,NULL,NULL,NULL,9.5,'Best food truck I’ve been to in ages. Smash burger and Mac and cheese just slapped. Heard from the owner they make everything very fresh every day and that’s why the food is such high quality. Loaded option is best bet for big feed. Definitely go here when you’re craving a big meal!',1,NULL,'published',1779017842,1779017842);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(194,317,'the-meat-wine-co-circular-quay-o-connell-st-2025-06-07','2025-06-07','dinner',6.5,NULL,NULL,NULL,NULL,7,'Pretty average and overhyped.',1,NULL,'published',1779023377,1779023377);
INSERT INTO "reviews" ("id","restaurant_id","slug","visit_date","meal_type","rating_overall","rating_food","rating_vibe","rating_service","rating_value","rating_size","commentary","would_return","instagram_url","status","created_at","updated_at") VALUES(195,106,'the-gidley-2024-04-17','2024-04-17','dinner',8,NULL,NULL,NULL,NULL,7,'Solid place, would recommend the cheeseburger.',1,NULL,'published',1779023483,1779023483);
